    "    if (prefix.length >= maxLen) return;",
    "    const start = prefix.length === 0 ? minVal : prefix[prefix.length - 1];",
    "    for (let v = start; v <= maxVal; v++) {",
    "      prefix.push(v);",
    "      rec(prefix, minVal, maxVal, maxLen);",
