    const outcome = await new Promise((resolve) => {
      let settled = false;
      const settle = (v) => { if (!settled) { settled = true; resolve(v); } };
      let stdout = '';
      const child = spawn(process.execPath, [runnerPath, payloadPath], {
        stdio: ['ignore', 'pipe', 'ignore'],
        cwd: tmpDir,
        env: { NO_COLOR: '1' }
      });
      const timer = setTimeout(() => {
        try { child.kill('SIGKILL'); } catch (e) {}
        settle({ accept: false, reason: 'timeout waiting for test suite' });
      }, 12000);
      child.stdout.on('data', (c) => { stdout += c.toString(); });
      child.on('error', (err) => {
        clearTimeout(timer);
        settle({ accept: false, reason: 'spawn failed: ' + String(err) });
      });
      child.on('close', () => {
        clearTimeout(timer);
        let parsed = null;
        try {
          const data = JSON.parse(fs.readFileSync(resultPath, 'utf8'));
          if (data.nonce === nonce && data.done === true) parsed = data;
        } catch (e) {}
        for (const line of stdout.split('\n')) {
          if (!line.startsWith('GATE_RESULT_')) continue;
          try {
            const d = JSON.parse(line.slice('GATE_RESULT_'.length));
            if (d.nonce === nonce && d.done === true) parsed = d;
          } catch (e) {}
        }
        if (!parsed || parsed.nonce !== nonce || parsed.done !== true) {
          settle({ accept: false, reason: 'inauthentic or incomplete suite result' });
          return;
        }
        settle({ accept: !!parsed.accept, reason: String(parsed.reason || '') });
      });
    });
