  } finally {
    try { fs.unlinkSync(runnerPath); } catch (e) {}
    try { fs.unlinkSync(resultPath); } catch (e) {}
    try { fs.unlinkSync(payloadPath); } catch (e) {}
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (e) {}
    try { fs.rmSync(secretDir, { recursive: true, force: true }); } catch (e) {}
  }
}
