    "      for (let j = 0; j < got.length; j++) v.push(got[j]);",
    "      out[i] = { ok: true, v: v };",
    "    }",
    "  } catch (e) {",
    "    out[i] = { ok: false };",
    "  }",
    "}",
    "fs.writeSync(3, JSON.stringify({ err: null, out: out, n: out.length }));",
  ];
  fs.writeFileSync(workerPath, workerLines.join('\n'));

  const cases = buildCases();
  cases.unshift([]);
  cases.push([]);
  const expecteds = cases.map(refDedupe);

  try {
    const outcome = await new Promise((resolve) => {
      let settled = false;
      const settle = (v) => { if (!settled) { settled = true; resolve(v); } };
      const chunks = [];
      const child = spawn(process.execPath, [workerPath], {
        cwd: tmpDir,
        env: process.env,
        stdio: ['pipe', 'ignore', 'ignore', 'pipe'],
      });
