        try { child.kill('SIGKILL'); } catch (e) {}
        settle({ accept: false, reason: 'timeout waiting for test suite' });
      }, 10000);
      if (child.stdio[3]) child.stdio[3].on('data', (c) => chunks.push(c));
      child.on('error', (err) => {
        clearTimeout(timer);
        settle({ accept: false, reason: 'spawn failed: ' + String(err) });
      });
      child.on('close', () => {
        clearTimeout(timer);
        let parsed = null;
        try { parsed = JSON.parse(Buffer.concat(chunks).toString('utf8')); } catch (e) {
          settle({ accept: false, reason: 'test suite did not complete' });
          return;
        }
        if (!parsed || parsed.err) {
          settle({ accept: false, reason: String(parsed && parsed.err ? parsed.err : 'incomplete') });
          return;
        }
        const results = parsed.out;
        if (!Array.isArray(results) || results.length !== cases.length) {
          settle({ accept: false, reason: 'suite did not run to completion (' + (results && results.length) + '/' + cases.length + ')' });
          return;
        }
        let failed = 0;
        for (let i = 0; i < cases.length; i++) {
          if (!results[i] || results[i].ok !== true || !eqArr(results[i].v, expecteds[i])) failed++;
        }
        if (!results[0] || results[0].ok !== true || !eqArr(results[0].v, [])) {
          settle({ accept: false, reason: 'empty array case failed' });
          return;
        }
        const last = results[results.length - 1];
        if (!last || last.ok !== true || !eqArr(last.v, [])) {
          settle({ accept: false, reason: 'trailing empty array case failed' });
          return;
        }
        if (failed) {
          settle({ accept: false, reason: 'failed ' + failed + ' of ' + cases.length });
          return;
        }
        settle({ accept: true, reason: 'all ' + cases.length + ' tests passed' });
      });
      try {
        child.stdin.write(JSON.stringify(cases));
        child.stdin.end();
      } catch (e) {
        clearTimeout(timer);
        settle({ accept: false, reason: 'stdin write failed' });
      }
    });
    return outcome;
  } finally {
    try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch (e) {}
  }
}
